const complejoData = $input.first().json;
// Obtener datos del trigger passthrough
const triggerData = $('Entrada Handler Negocio').first().json;

const nombreComplejo = complejoData.name || 'nuestro complejo deportivo';
const pushName = triggerData.pushName || 'amigo';
const isImage = triggerData.isImage;
const msg = (triggerData.messageText || '').toLowerCase().trim();

let reply = '';

if (isImage) {
  reply = `¡Gracias ${pushName}! 📄 Hemos recibido tu comprobante de pago. Nuestro equipo lo verificará y te confirmará la reserva en unos minutos.`;
} else if (msg.includes('hola') || msg.includes('buenas') || msg.includes('precio') || msg.includes('cancha')) {
  reply = `¡Hola ${pushName}! 👋 Bienvenido a *${nombreComplejo}*.

Para consultar la disponibilidad de canchas y reservar, indícanos:
1️⃣ La fecha que buscas (ej. hoy, mañana o YYYY-MM-DD)
2️⃣ El tipo de cancha o deporte

¿En qué fecha deseas jugar?`;
} else {
  reply = `Hola ${pushName}, gracias por comunicarte con *${nombreComplejo}*. Estamos procesando tu mensaje. Si deseas reservar, por favor indícanos la fecha y hora de tu preferencia.`;
}

return {
  json: {
    ...triggerData,
    complejo: complejoData,
    replyText: reply
  }
};
